  'testing-p4' => 'उपयोगकर्ता परीक्षण सर्वोत्तम प्रतिक्रिया प्रदान करता है। वास्तविक सहायक तकनीक का उपयोग करने वाले विकलांग उपयोगकर्ता वास्तविक दुनिया की पहुंच संबंधी समस्याओं की पहचान करते हैं।',
  'compliance-heading' => 'अनुपालन मानक',
  'compliance-p1' => 'WCAG (वेब ​​कंटेंट एक्सेसिबिलिटी दिशानिर्देश) एक्सेसिबिलिटी मानक प्रदान करते हैं। पीडीएफ अभिगम्यता दिशानिर्देश (पीडीएफ/यूए) विशेष रूप से पीडीएफ को संबोधित करते हैं।',
  'compliance-p2' => 'लेवल ए अनुपालन बुनियादी है। न्यूनतम आवश्यकताओं को पूरा करता है.',
  'compliance-p3' => 'स्तर एए अनुपालन की अनुशंसा की जाती है। अधिकांश उपयोगकर्ताओं के लिए व्यापक पहुंच सुनिश्चित करता है।',
  'compliance-p4' => 'स्तर एएए अनुपालन मानक आवश्यकताओं से अधिक है। उन्नत पहुंच प्रदान करता है.',
  'compliance-p5' => 'सरकार और सार्वजनिक संगठनों को आम तौर पर लेवल एए पूरा करना आवश्यक होता है। निजी संगठन तेजी से लेवल एए का लक्ष्य बना रहे हैं।',
  'types-heading' => 'विभिन्न दस्तावेज़ प्रकारों में पहुंच',
  'types-p1' => 'रिपोर्ट में उचित शीर्षक पदानुक्रम के साथ स्पष्ट संरचना होनी चाहिए। तालिकाओं में शीर्षकों को उचित रूप से चिह्नित किया जाना आवश्यक है।',
  'types-p2' => 'प्रपत्रों को उचित लेबल और संगठन की आवश्यकता होती है। निर्देश स्पष्ट और व्यापक होने चाहिए.',
  'types-p3' => 'प्रस्तुतियों में ऑडियो के लिए प्रतिलेख और वीडियो के लिए कैप्शन होने चाहिए। पाठ-आधारित संस्करण उपलब्ध होने चाहिए.',
  'types-p4' => 'बहुभाषी दस्तावेज़ों में भाषा अनुभागों को टैग किया जाना चाहिए। सही ढंग से उच्चारण करने के लिए स्क्रीन रीडर्स को भाषा परिवर्तन जानना आवश्यक है।',
  'benefits-heading' => 'अनुपालन से परे लाभ',
  'benefits-p1' => 'पहुंच-योग्यता में सुधार से सभी को लाभ होता है। स्पष्ट संरचना सभी उपयोगकर्ताओं को नेविगेट करने में मदद करती है। बड़े फ़ॉन्ट उपयोगकर्ताओं को छोटी स्क्रीन पर देखने में मदद करते हैं। कैप्शन उपयोगकर्ताओं को शोर-शराबे वाले वातावरण में मदद करते हैं।',
  'benefits-p2' => 'सुलभ दस्तावेज़ खोज रैंकिंग में बेहतर स्कोर करते हैं। खोज इंजन उचित संरचना और पहुंच मार्कअप वाले दस्तावेज़ों को पसंद करते हैं।',
  'benefits-p3' => 'अभिगम्यता समावेशन के प्रति प्रतिबद्धता को प्रदर्शित करती है। सुलभ दस्तावेज़ प्रकाशित करने वाले संगठन सभी उपयोगकर्ताओं को सेवा देने की प्रतिबद्धता का संकेत देते हैं।',
  'benefits-p4' => 'बार-बार दस्तावेज़ बनाने और साझा करने वाले संगठनों के लिए, पहुंच मानक अभ्यास होनी चाहिए। सुलभ पीडीएफ को दस्तावेज़ वर्कफ़्लो के साथ एकीकृत किया जाना चाहिए ताकि प्रारूप रूपांतरणों के माध्यम से पहुंच सुनिश्चित हो सके। इसी प्रकार, जब __MERGE_LINK__ दस्तावेज़ सुलभ हों, तो सुनिश्चित करें कि मर्ज किए गए परिणाम स्रोत दस्तावेज़ों की पहुंच बनाए रखें।',
  'mistakes-heading' => 'सामान्य अभिगम्यता गलतियाँ',
  'mistakes-p1' => 'यह मानते हुए कि स्कैन किए गए दस्तावेज़ पहुंच योग्य हैं क्योंकि वे पीडीएफ रीडर में खुलते हैं। स्कैन की गई पीडीएफ छवियां हैं। पहुंच के लिए ओसीआर रूपांतरण आवश्यक है।',
  'mistakes-p2' => 'वैकल्पिक पाठ को वैकल्पिक के रूप में अनदेखा करना। स्क्रीन रीडर उपयोगकर्ताओं के लिए ऑल्ट टेक्स्ट आवश्यक है। ऑल्ट टेक्स्ट को कभी न छोड़ें।',
  'mistakes-p3' => 'जानकारी संप्रेषित करने के लिए केवल रंग का उपयोग करना। कलरब्लाइंड उपयोगकर्ता केवल रंग वाली जानकारी में अंतर नहीं कर सकते।',
  'mistakes-p4' => 'स्क्रीन रीडर्स के साथ परीक्षण नहीं किया जा रहा है। सैद्धांतिक पहुंच अक्सर वास्तविक दुनिया के उपयोगकर्ता अनुभव से भिन्न होती है।',
  'mistakes-p5' => 'यह मानते हुए कि पहुंच एक बार की परियोजना है। सुगम्यता पर निरंतर ध्यान देने की आवश्यकता है। नए दस्तावेज़ों को पहुंच-योग्यता जांच की आवश्यकता होती है.',
  'conclusion-heading' => 'निष्कर्ष',
  'conclusion-p1' => 'सुलभ पीडीएफ बनाने से यह सुनिश्चित होता है कि विकलांग उपयोगकर्ता दस्तावेज़ पढ़ सकते हैं। पहुंच-योग्यता कानूनी आवश्यकता और नैतिक अभ्यास दोनों है।',
  'conclusion-p2' => 'OCR टेक्स्ट निष्कर्षण का उपयोग करके स्कैन किए गए दस्तावेज़ों को परिवर्तित करके प्रारंभ करें। सुनिश्चित करें कि सभी दस्तावेज़ों में उचित संरचना, वैकल्पिक पाठ और स्पष्ट स्वरूपण हो।',
  'conclusion-p3' => 'स्क्रीन रीडर और एक्सेसिबिलिटी चेकर्स के साथ एक्सेसिबिलिटी का परीक्षण करें। विकलांग उपयोगकर्ताओं से प्रतिक्रिया एकत्र करें.',
  'conclusion-p4' => 'पहुंच को मानक अभ्यास बनाएं। प्रत्येक दस्तावेज़ को पहुंच-योग्यता मानकों को पूरा करना चाहिए।',
  'conclusion-p5' => 'सुलभ दस्तावेज़ बेहतर स्पष्टता और संरचना के माध्यम से सभी को लाभान्वित करते हैं। सभी उपयोगकर्ताओं के लिए सुलभ समावेशी दस्तावेज़ बनाने के लिए प्रतिबद्ध रहें।',
);
